import 'package:flutter/material.dart';import 'package:myapp/models/user_model.dart';import 'package:myapp/repositories/auth_repository.dart';import 'package:myapp/repositories/user_repository.dart';class SettingsViewModel extends ChangeNotifier {  final AuthRepository _authRepository;  final UserRepository _userRepository;  UserModel? _currentUser;  bool _isLoading = false;  bool _notificationsEnabled = true;  SettingsViewModel(this._authRepository, this._userRepository);  UserModel? get currentUser => _currentUser;  bool get isLoading => _isLoading;  bool get notificationsEnabled => _notificationsEnabled;  void setUser(UserModel? user) {    _currentUser = user;    notifyListeners();  }  void setLoading(bool value) {    _isLoading = value;    notifyListeners();  }  void setNotifications(bool enabled) {    _notificationsEnabled = enabled;    notifyListeners();  }  void toggleNotifications() {    _notificationsEnabled = !_notificationsEnabled;    notifyListeners();  }  Future<void> changePassword(String oldPassword, String newPassword) async {    if (_currentUser == null) return;    if (_currentUser!.password != oldPassword) {      throw Exception('Old password is incorrect');    }    final updated = _currentUser!.copyWith(password: newPassword);    await _userRepository.updateUser(updated);    _currentUser = updated;    await _authRepository.setCurrentUser(updated);    notifyListeners();  }  Future<void> updateProfile(String username, String email) async {    if (_currentUser == null) return;    final updated = _currentUser!.copyWith(      username: username,      email: email,    );    await _userRepository.updateUser(updated);    _currentUser = updated;    await _authRepository.setCurrentUser(updated);    notifyListeners();  }}